import numpy as np
import pandas as pd
import pickle
import os

def load_pickle(file_path):
    with open(file_path, 'rb') as f:
        return pickle.load(f)

def analyze_array(name, arr):
    print(f"\n=== Analysis for {name} ===")
    print(f"Shape: {arr.shape}")
    print(f"Data type: {arr.dtype}")
    print(f"Min value: {np.min(arr)}")
    print(f"Max value: {np.max(arr)}")
    print(f"Mean value: {np.mean(arr)}")
    print(f"Standard deviation: {np.std(arr)}")
    print(f"Sample values (first 5):\n{arr[:5]}")

    # Check if data appears normalized
    if np.issubdtype(arr.dtype, np.number):
        if np.min(arr) >= -1 and np.max(arr) <= 1:
            print("Data appears to be normalized to [-1, 1] range")
        elif np.min(arr) >= 0 and np.max(arr) <= 1:
            print("Data appears to be normalized to [0, 1] range")
        else:
            print("Data does not appear to be normalized")

    # Check if data might be image data
    if len(arr.shape) >= 2:
        if len(arr.shape) == 4:
            print(f"Data appears to be image data with format: {arr.shape[0]} images of size {arr.shape[1]}x{arr.shape[2]} with {arr.shape[3]} channels")
        elif len(arr.shape) == 3:
            print(f"Data appears to be image data with format: {arr.shape[0]} images of size {arr.shape[1]}x{arr.shape[2]}")
        elif arr.shape[-1] in [1, 3, 4]:
            print("Data could be flattened image data")

# Load and analyze data
input_dir = "/home/ctfplayer/ctf_files/inputs"
files = ['X.pkl', 'X_test.pkl', 'y.pkl']

for file in files:
    file_path = os.path.join(input_dir, file)
    try:
        data = load_pickle(file_path)
        analyze_array(file, data)
    except Exception as e:
        print(f"Error loading {file}: {str(e)}")

